def analyze(i,o,bgc,blk,tag):
    H,W=len(i),len(i[0])
    rows=[]
    for r in range(H):
        for c in range(W):
            if i[r][c]!=bgc: continue
            hurs=False; hul=False; hdl=False; hdr=False
            for dr,dc,name in [(-1,1,'ur'),(-1,-1,'ul'),(1,-1,'dl'),(1,1,'dr')]:
