                    rr,cc=r-1,c-1
                    while 0<=rr<H and 0<=cc<W:
                        if i[rr][cc]==blk: hul=True; break
                        rr-=1; cc-=1
                elif name=='dl':
                    rr,cc=r+1,c-1
                    while 0<=rr<H and 0<=cc<W:
                        if i[rr][cc]==blk: hdl=True; break
                        rr+=1; cc-=1
                else:
                    rr,cc=r+1,c+1
                    while 0<=rr<H and 0<=cc<W:
                        if i[rr][cc]==blk: hdr=True; break
                        rr+=1; cc+=1
            act=o[r][c]
            sig=(hurs,hul,hdl,hdr)
            rows.append((sig,act))
    from collections import Counter
    c=Counter()
    for sig,act in rows: c[(sig,act)]+=1
    print(tag)
    for k,v in sorted(c.items()): print(' ',k,v)
