    for r in range(H):
        for c in (0,W-1):
            if g[r][c]==bgv and not reach[r][c]: reach[r][c]=True; stack=[(r,c)]
    for c in range(W):
        for r in (0,H-1):
            if g[r][c]==bgv and not reach[r][c]: reach[r][c]=True; stack=[(r,c)]
    while stack:
